BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE u uuid:=gen_random_uuid();o uuid:=gen_random_uuid();a uuid:=gen_random_uuid();x uuid:=gen_random_uuid();v uuid:=gen_random_uuid();m uuid;owner uuid;other uuid;viewer uuid;f uuid;hidden uuid;r jsonb;again jsonb;rid uuid;jobs jsonb;job jsonb;second jsonb;page jsonb;before_count integer;rate_folder uuid;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(u,'requester@example.invalid',now()),(o,'owner@example.invalid',now()),(a,'admin@example.invalid',now()),(x,'other@example.invalid',now()),(v,'viewer@example.invalid',now());
 INSERT INTO public.user_roles VALUES(a,'admin');
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(u,'user','Requester') RETURNING id INTO m;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(o,'user','Folder owner') RETURNING id INTO owner;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(x,'user','Other member') RETURNING id INTO other;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label,role) VALUES(v,'user','Workspace viewer','viewer') RETURNING id INTO viewer;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Requests','view') RETURNING id INTO f;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Hidden requests','none') RETURNING id INTO hidden;
 INSERT INTO public.redirect_folder_members VALUES(f,owner,'owner');
 BEGIN PERFORM public.redirect_access_request('create',m,p_folder=>hidden);RAISE EXCEPTION 'Private folder request disclosed existence';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.redirect_access_request('create',m,p_folder=>f,p_message=>'Please let me update campaign targets');rid:=(r->>'id')::uuid;
 again:=public.redirect_access_request('create',m,p_folder=>f,p_message=>'Repeated click');
 IF again->>'id'<>r->>'id' OR NOT(again->>'duplicate')::boolean THEN RAISE EXCEPTION 'Request duplication';END IF;
 IF (SELECT count(*) FROM public.notifications WHERE related_id=rid)<>2 OR (SELECT count(*) FROM public.redirect_access_mail WHERE request_id=rid)<>2 THEN RAISE EXCEPTION 'Owner/admin notices not atomic or duplicated';END IF;
 IF EXISTS(SELECT FROM public.redirect_access_mail WHERE request_id=rid AND event<>'requested') THEN RAISE EXCEPTION 'Wrong notification event';END IF;
 page:=public.redirect_access_requests_page(other,'review');IF (page->>'count')::int<>0 THEN RAISE EXCEPTION 'Nonowner read review requests';END IF;
 BEGIN PERFORM public.redirect_access_request('approve',other,rid);RAISE EXCEPTION 'Nonowner approved';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 page:=public.redirect_access_requests_page(owner,'review');IF (page->>'count')::int<>1 OR page#>>'{data,0,member_label}'<>'Requester' THEN RAISE EXCEPTION 'Owner review missing';END IF;
 r:=public.redirect_access_request('approve',owner,rid,p_permission=>'edit');
 IF r->>'status'<>'approved' OR r->>'decided_by'<>o::text OR public.redirect_folder_rank(m,f)<>2 THEN RAISE EXCEPTION 'Approval did not grant edit atomically';END IF;
 PERFORM public.redirect_workspace_resource('folders','update',f,'{"name":"Editor renamed"}',p_token_id=>m);
 IF public.redirect_workspace_resource('folders','get',f,p_token_id=>m)->>'name'<>'Editor renamed' THEN RAISE EXCEPTION 'Editor could not rename folder';END IF;
 IF EXISTS(SELECT FROM public.redirect_access_mail WHERE request_id=rid AND event='requested' AND state<>'cancelled') THEN RAISE EXCEPTION 'Obsolete request emails remained queued';END IF;
 BEGIN PERFORM public.redirect_access_request('deny',owner,rid);RAISE EXCEPTION 'Resolved request was replayed';EXCEPTION WHEN unique_violation THEN NULL;END;
 jobs:=public.claim_redirect_access_mail('Queer Guide <noreply@queer.guide>');
 IF jsonb_array_length(jobs)<>1 OR jobs#>>'{0,email}'<>'requester@example.invalid' OR jobs#>>'{0,event}'<>'approved' THEN RAISE EXCEPTION 'Decision mail audience incorrect';END IF;
 job:=jobs->0;
 IF public.finish_redirect_access_mail((job->>'id')::uuid,gen_random_uuid(),'wrong') THEN RAISE EXCEPTION 'Wrong lease acknowledged';END IF;
 PERFORM public.finish_redirect_access_mail((job->>'id')::uuid,(job->>'leaseId')::uuid,p_error=>'HTTP 429',p_retry_after=>900);
 IF (SELECT state<>'queued' OR next_attempt_at<clock_timestamp()+interval '14 minutes' FROM public.redirect_access_mail WHERE id=(job->>'id')::uuid) THEN RAISE EXCEPTION 'Retry backoff ignored provider delay';END IF;
 IF jsonb_array_length(public.claim_redirect_access_mail('changed@example.invalid'))<>0 THEN RAISE EXCEPTION 'Not-yet-due job reclaimed';END IF;
 UPDATE public.redirect_access_mail SET next_attempt_at=now()-interval '1 second' WHERE id=(job->>'id')::uuid;
 second:=public.claim_redirect_access_mail('changed@example.invalid')->0;
 IF second->>'from'<>job->>'from' OR second->>'leaseId'=job->>'leaseId' THEN RAISE EXCEPTION 'Retry payload/lease unstable';END IF;
 IF public.finish_redirect_access_mail((job->>'id')::uuid,(job->>'leaseId')::uuid,'stale') THEN RAISE EXCEPTION 'Old lease acknowledged new claim';END IF;
 PERFORM public.finish_redirect_access_mail((second->>'id')::uuid,(second->>'leaseId')::uuid,'provider-receipt');
 IF jsonb_array_length(public.claim_redirect_access_mail('sender@example.invalid'))<>0 THEN RAISE EXCEPTION 'Sent notification duplicated';END IF;
 r:=public.redirect_access_request('create',viewer,p_folder=>f);rid:=(r->>'id')::uuid;
 BEGIN PERFORM public.redirect_access_request('approve',owner,rid);RAISE EXCEPTION 'Folder approval upgraded workspace viewer';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_folder_rank(viewer,f)<>1 OR (SELECT status FROM public.redirect_access_requests WHERE id=rid)<>'pending' THEN RAISE EXCEPTION 'Denied approval partially changed ACL';END IF;
 BEGIN PERFORM public.redirect_access_request('cancel',other,rid);RAISE EXCEPTION 'Other member cancelled request';EXCEPTION WHEN no_data_found THEN NULL;END;
 PERFORM public.redirect_access_request('cancel',viewer,rid);
 r:=public.redirect_access_request('create',viewer,p_folder=>f);
 IF (r->>'retryAfter')::int NOT BETWEEN 1 AND 86400 THEN RAISE EXCEPTION 'Daily folder request limit missing';END IF;
 UPDATE public.redirect_folder_members SET permission='view' WHERE folder_id=f AND member_id=m;
 r:=public.redirect_access_request('create',other,p_folder=>f);rid:=(r->>'id')::uuid;
 jobs:=public.claim_redirect_access_mail('sender@example.invalid');IF jsonb_array_length(jobs)<>2 THEN RAISE EXCEPTION 'Pending request did not queue owner/admin mail';END IF;
 UPDATE public.redirect_access_mail SET lease_until=now()-interval '1 second' WHERE request_id=rid;
 DELETE FROM public.user_roles WHERE user_id=a;
 UPDATE public.redirect_folder_members SET permission='view' WHERE folder_id=f AND member_id=owner;
 jobs:=public.claim_redirect_access_mail('sender@example.invalid');
 IF jsonb_array_length(jobs)<>0 OR EXISTS(SELECT FROM public.redirect_access_mail WHERE request_id=rid AND state<>'cancelled') THEN RAISE EXCEPTION 'Former owners still received pending mail';END IF;
 INSERT INTO public.redirect_folder_members VALUES(hidden,owner,'owner');
 INSERT INTO public.redirect_folder_members VALUES(hidden,m,'view');
 r:=public.redirect_access_request('create',m,p_folder=>hidden);rid:=(r->>'id')::uuid;
 UPDATE public.redirect_access_mail SET first_attempt_at=now()-interval '24 hours',attempts=1 WHERE request_id=rid;
 jobs:=public.claim_redirect_access_mail('sender@example.invalid');
 IF jsonb_array_length(jobs)<>0 OR (SELECT state FROM public.redirect_access_mail WHERE request_id=rid)<>'failed' THEN RAISE EXCEPTION 'Ambiguous send retried outside idempotency window';END IF;
 UPDATE auth.users SET email='changed@example.invalid' WHERE id=o;
 UPDATE public.redirect_access_mail SET state='queued',first_attempt_at=NULL,attempts=0 WHERE request_id=rid;
 jobs:=public.claim_redirect_access_mail('sender@example.invalid');
 IF jsonb_array_length(jobs)<>0 OR (SELECT state FROM public.redirect_access_mail WHERE request_id=rid)<>'cancelled' THEN RAISE EXCEPTION 'Changed recipient address received a stale email';END IF;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Rate limited','view') RETURNING id INTO rate_folder;
 INSERT INTO public.redirect_folder_members VALUES(rate_folder,owner,'owner');
 INSERT INTO public.redirect_access_requests(folder_id,member_id,status) SELECT f,other,'denied' FROM generate_series(1,9);
 SELECT count(*) INTO before_count FROM public.notifications;
 r:=public.redirect_access_request('create',other,p_folder=>rate_folder);
 IF (r->>'retryAfter')::int<>86400 OR (SELECT count(*) FROM public.notifications)<>before_count THEN RAISE EXCEPTION 'Actor request limit failed';END IF;
 page:=public.redirect_access_requests_page(other,'mine',3);
 IF (page->>'count')::int<>10 OR jsonb_array_length(page->'data')<>3 OR page->>'nextCursor' IS NULL THEN RAISE EXCEPTION 'Request pagination count failed';END IF;
 again:=public.redirect_access_requests_page(other,'mine',3,(page->>'nextCursor')::uuid);
 IF jsonb_array_length(again->'data')<>3 OR EXISTS(SELECT FROM jsonb_array_elements(again->'data') e WHERE (e->>'id')::uuid<=(page->>'nextCursor')::uuid) THEN RAISE EXCEPTION 'Request page repeated records';END IF;
END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 IF has_function_privilege(current_user,'public.redirect_access_recipient(uuid)','execute') OR has_function_privilege(current_user,'public.redirect_access_request(text,uuid,uuid,uuid,text,text,uuid)','execute') OR has_function_privilege(current_user,'public.claim_redirect_access_mail(text,integer)','execute') THEN RAISE EXCEPTION 'Private request/mail RPC exposed';END IF;
 BEGIN PERFORM * FROM public.redirect_access_requests;RAISE EXCEPTION 'Requests exposed via Data API';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM * FROM public.redirect_access_mail;RAISE EXCEPTION 'Recipient addresses exposed via Data API';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
ROLLBACK;
